fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Check if the string is non-empty
    if txt.is_empty() {
        return false;
    }

    // Get the last character
    let last_char = txt.chars().last().unwrap(); // Safe to unwrap since we checked for non-empty

    // Check if the last character is an ASCII letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Check the conditions for the preceding character
    let len = txt.len();
    if len == 1 {
        // If the string has exactly one character, it's valid
        return true;
    } else {
        // Check if the character before the last is a space
        let second_last_char = txt.chars().nth(len - 2).unwrap(); // Safe to unwrap since len > 1
        return second_last_char == ' ';
    }
}